        {"kind": "trace", "sql": "SELECT 'normal' p, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, avg(duration)/1e6 avg_ms FROM normal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*), quantile_cont(duration,0.95)/1e6, avg(duration)/1e6 FROM abnormal_traces WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 ORDER BY 2,1", "claim": "ts-route-service's SELECT DB client spans rose from about 0.1-0.7 ms p95 to about 207-423 ms p95."},
        {"kind": "metric", "sql": "SELECT * FROM (SELECT 'n' p, metric, service_name, avg(value) v FROM normal_metrics WHERE service_name IN ('mysql','ts-route-service') GROUP BY 1,2,3 UNION ALL SELECT 'a', metric, service_name, avg(value) FROM abnormal_metrics WHERE service_name IN ('mysql','ts-route-service') GROUP BY 1,2,3) ORDER BY 2,3,1", "claim": "mysql and ts-route-service CPU stayed low or fell in the incident, so no resource saturation explains the slow DB calls."},
        {"kind": "metric", "sql": "SELECT 'n' p, service_name, metric, count(*) n, max(value) mx FROM normal_metrics WHERE metric='k8s.container.restarts' GROUP BY 1,2,3 UNION ALL SELECT 'a', service_name, metric, count(*), max(value) FROM abnormal_metrics WHERE metric='k8s.container.restarts' GROUP BY 1,2,3", "claim": "Container restart counts are unchanged between normal and abnormal periods, so no restart caused the slowdown."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms, avg(duration)/1e6 avg_ms FROM abnormal_traces WHERE service_name IN ('ts-route-service','ts-basic-service','ts-travel-service','ts-travel2-service','ts-route-plan-service') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,4 DESC", "claim": "Server spans in route-service's callers (basic, travel, travel2, route-plan) show multi-hundred-millisecond p95 in abnormal period."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-route-service", "to": "ts-basic-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name IN ('ts-basic-service','ts-route-service') AND attr_span_kind='Server' GROUP BY 1,2 ORDER BY 1,4 DESC", "claim": "ts-basic-service server spans slow to about 220 ms p95 while its own work stays about 3-4 ms; the wait is on route-service calls."}]},
    {"from": "ts-route-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-travel-service server p95 rose to about 225 ms in the abnormal period, driven by its calls to route-service and basic-service."}]},
    {"from": "ts-route-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-route-plan-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-route-plan-service server p95 rose to about 2,350 ms in the abnormal period while its own time stayed flat."}]},
    {"from": "ts-basic-service", "to": "ts-travel2-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-travel2-service server p95 rose to about 390 ms, consistent with its calls to basic-service and route-service being slow."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-travel-plan-service server p95 rose to about 2,356 ms, inheriting the route-plan-service delay."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-ui-dashboard, the user-facing entry, shows server p95 of about 2,430 ms in the abnormal period."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-ui-dashboard server latency rose to about 2,430 ms; its travel2 calls inherit the route-service delay."}]},
    {"from": "ts-route-service", "to": "ts-admin-route-service", "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-admin-route-service' AND attr_span_kind='Server' GROUP BY 1,2", "claim": "ts-admin-route-service server p95 rose to about 5,100 ms, with its Client calls to route-service slow."}]}
